using System.Text.Json;
using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evaluation;

[TestClass]
public class EvaluationTests
{
    private static DistributedApplicationTestingBuilder _appHost = null!;
    private static IChatClient _chatClient = null!;
    private static IChatClient _evaluatorClient = null!;
    private static List<Scenario> _scenarios = [];

    [ClassInitialize]
    public static async Task ClassInitialize(TestContext context)
    {
        _appHost = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        var app = await _appHost.BuildAsync();
        await app.StartAsync();

        _chatClient = app.Services.GetRequiredService<IChatClient>();
        _evaluatorClient = _chatClient;

        var scenarioJson = await File.ReadAllTextAsync("scenarios.json");
        _scenarios = JsonSerializer.Deserialize<List<Scenario>>(scenarioJson, new JsonSerializerOptions
        {
            PropertyNameCaseInsensitive = true
        }) ?? [];
    }

    [ClassCleanup]
    public static async Task ClassCleanup()
    {
        if (_appHost is IAsyncDisposable disposable)
            await disposable.DisposeAsync();
    }

    [TestMethod]
    public async Task Evaluate_Relevance()
    {
        var evaluator = new RelevanceEvaluator();

        foreach (var scenario in _scenarios)
        {
            var messages = new List<ChatMessage>
            {
                new(ChatRole.User, scenario.Prompt)
            };

            var response = await _chatClient.GetResponseAsync(messages);
            messages.Add(response.Message);

            var result = await evaluator.EvaluateAsync(messages, _evaluatorClient);

            Assert.IsTrue(
                result.All(m => m.Rating?.Value >= 3),
                $"Scenario '{scenario.Name}' failed relevance check.");
        }
    }

    [TestMethod]
    public async Task Evaluate_Coherence()
    {
        var evaluator = new CoherenceEvaluator();

        foreach (var scenario in _scenarios)
        {
            var messages = new List<ChatMessage>
            {
                new(ChatRole.User, scenario.Prompt)
            };

            var response = await _chatClient.GetResponseAsync(messages);
            messages.Add(response.Message);

            var result = await evaluator.EvaluateAsync(messages, _evaluatorClient);

            Assert.IsTrue(
                result.All(m => m.Rating?.Value >= 3),
                $"Scenario '{scenario.Name}' failed coherence check.");
        }
    }

    [TestMethod]
    public async Task Evaluate_Responses_NotEmpty()
    {
        foreach (var scenario in _scenarios)
        {
            var messages = new List<ChatMessage>
            {
                new(ChatRole.User, scenario.Prompt)
            };

            var response = await _chatClient.GetResponseAsync(messages);

            Assert.IsFalse(
                string.IsNullOrWhiteSpace(response.Message.Text),
                $"Scenario '{scenario.Name}' returned an empty response.");
        }
    }
}

public record Scenario(string Name, string Prompt, List<string> ExpectedTopics);

